{
  "name": "LabRAD异步客户端",
  "name_en": "LabRAD Asynchronous Client",
  "manufacturer": "",
  "description": "这是一个用于实验室自动化系统中与远程 LabRAD 服务器通信的软件客户端组件。它支持异步连接、创建通信上下文、构建并发送请求或数据包、发送消息，以及管理监听器和断开连接事件，常用于实验控制网络中的服务访问与消息交互。",
  "description_en": "This is a software client component for communicating with remote LabRAD servers in laboratory automation systems. It supports asynchronous connections, creation of communication contexts, building and sending requests or packets, sending messages, and managing listeners and disconnect events, and is commonly used for service access and message exchange in experiment-control networks.",
  "tag_hints": [
    "LabRAD",
    "asynchronous client",
    "laboratory automation",
    "remote server communication",
    "packet-based requests",
    "message listeners"
  ],
  "actions": [
    {
      "action_name": "auto-refresh",
      "description": "刷新远程 LabRAD 服务及其设定的可用信息。",
      "description_en": "Refresh the available information about remote LabRAD servers and their settings."
    },
    {
      "action_name": "auto-context",
      "description": "为当前连接创建新的通信上下文。",
      "description_en": "Create a new communication context for the current connection."
    },
    {
      "action_name": "auto-spawn",
      "description": "派生一个新的异步客户端实例或独立通信会话。",
      "description_en": "Spawn a new asynchronous client instance or independent communication session."
    },
    {
      "action_name": "auto-disconnect",
      "description": "断开与 LabRAD 网络或远程服务的连接。",
      "description_en": "Disconnect from the LabRAD network or remote services."
    },
    {
      "action_name": "auto-create",
      "description": "根据给定的协议对象创建异步客户端。",
      "description_en": "Create an asynchronous client from the given protocol object."
    },
    {
      "action_name": "auto-onDisconnect",
      "description": "获取断开连接处理回调。",
      "description_en": "Get the disconnect handler callback."
    },
    {
      "action_name": "auto-send",
      "description": "发送请求或命令到远程 LabRAD 服务。",
      "description_en": "Send a request or command to a remote LabRAD service."
    },
    {
      "action_name": "auto-packet",
      "description": "创建用于批量请求的 LabRAD 数据包。",
      "description_en": "Create a LabRAD packet for batched requests."
    },
    {
      "action_name": "auto-sendMessage",
      "description": "发送一条 LabRAD 消息。",
      "description_en": "Send a LabRAD message."
    },
    {
      "action_name": "auto-addListener",
      "description": "添加消息或事件监听器。",
      "description_en": "Add a message or event listener."
    },
    {
      "action_name": "auto-removeListener",
      "description": "移除消息或事件监听器。",
      "description_en": "Remove a message or event listener."
    }
  ]
}

